+/* Device-aware fit: use the actual dynamic viewport and reserve safe areas for phone controls. */
+html,body,#game-shell{height:100%;height:100dvh;width:100%;width:100dvw}
+.orientation-gate{display:none;position:absolute;inset:0;z-index:20;align-items:center;justify-content:center;padding:24px;background:radial-gradient(ellipse at 50% 35%,rgba(51,67,48,.96),rgba(12,17,13,.99));text-align:center}
+.orientation-gate.visible{display:flex}
+.orientation-card{max-width:380px}
+.orientation-card h2{font:800 clamp(42px,12vw,66px)/.8 var(--display);letter-spacing:-.02em;margin:19px 0;color:var(--white)}
+.orientation-card h2 em{font-style:normal;color:var(--acid)}
+.orientation-card p{color:#c3cabb;font-size:13px;line-height:1.7;margin:20px 0}
+.orientation-arrows{font:10px var(--mono);letter-spacing:1.4px;color:var(--acid)}
+.rotate-device{display:block;color:var(--acid);font-size:38px;transform:rotate(90deg);margin-bottom:20px}
+.mobile-device .mobile-controls{display:block}
+.mobile-device #game-canvas,.mobile-device .topbar,.mobile-device .screen,.mobile-device .game-hud{touch-action:none}
+.mobile-device .touch-stick{left:max(18px,env(safe-area-inset-left));bottom:max(15px,env(safe-area-inset-bottom));width:clamp(78px,17vh,112px);height:clamp(78px,17vh,112px)}
+.mobile-device .touch-stick i{left:50%;top:50%;transform:translate(-50%,-50%)}
+.mobile-device .touch-actions{right:max(15px,env(safe-area-inset-right));bottom:max(14px,env(safe-area-inset-bottom));gap:10px}
+.mobile-device .touch-actions button{width:clamp(44px,9vh,58px);height:clamp(44px,9vh,58px);touch-action:none}
+.mobile-device .menu-bottom{padding-bottom:env(safe-area-inset-bottom)}
+@media (orientation:landscape) and (max-height:520px) and (max-width:1000px){
+  .topbar{height:42px;padding:0 3%;}
+  .brand{font-size:13px;gap:7px}.brand-mark{width:22px;height:22px;font-size:16px}
+  .top-center{font-size:7px;gap:5px}.icon-button{width:26px;height:26px}
+  .screen{align-items:center;overflow:hidden}
+  .menu-layout{width:94vw;height:calc(100dvh - 55px);max-width:1100px;margin:48px auto 8px;display:grid;grid-template-columns:.8fr 1.2fr;gap:4%;align-items:center}
+  .menu-copy{padding:0 0 0 2%;display:block}
+  .season-tag{font-size:7px;letter-spacing:1px;gap:6px}
+  .menu-copy h1{font-size:clamp(60px,16vh,88px);line-height:.72;margin:12px 0 12px}
+  .hero-copy{font-size:10px;line-height:1.45;margin:0 0 10px}
+  .menu-actions{gap:9px;flex-wrap:wrap;margin-top:8px}
+  .primary-button{height:37px;min-width:120px;padding:0 12px;font-size:10px;gap:26px}
+  .secondary-button{font-size:8px}
+  .hero-foot{display:none}
+  .map-select{padding:11px 15px;background:rgba(18,23,18,.8)}
+  .map-select-head{margin-bottom:7px}.map-select-head h2{font-size:19px;margin-top:2px}.map-total{font-size:19px}
+  .map-row{height:34px;grid-template-columns:27px 1fr 100px 12px;padding:0 7px}
+  .map-number,.map-biome{font-size:7px}.map-name{font-size:12px}
+  .map-detail{display:none}
+  .menu-bottom{display:none}
+  .match-card{top:52px;left:10px;transform:scale(.72);transform-origin:top left}
+  .objective{top:51px;gap:5px;padding:5px 7px}.objective strong{font-size:8px}.objective .eyebrow,.objective-count{font-size:6px}
